#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Reasonable tile sizes for a modern x64 CPU with many cores and wide SIMD.
// We tile more strongly in x (the contiguous dimension) than in y.
namespace {
constexpr int TILE_X = 128;  // tile size in the fast (x=j) dimension
constexpr int TILE_Y = 32;   // tile size in the slow (y=i) dimension
}  // namespace

/**
 * Halide-based initialization of A and B.
 *
 * Original C code:
 *
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++) {
 *       A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
 *       B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
 *     }
 *
 * We map A[i][j] -> A(j, i) and B[i][j] -> B(j, i) in Halide.
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // n as a Halide Expr, with the correct element type.
    Expr n_expr = cast<num_t>(n);

    // A(i,j) in C -> A(j,i) in Halide
    init_A(j, i) = cast<num_t>(i * (j + 2) + 2) / n_expr;
    // B(i,j) in C -> B(j,i) in Halide
    init_B(j, i) = cast<num_t>(i * (j + 3) + 3) / n_expr;

    // -------------------------------
    // Schedule for initialization
    // -------------------------------
    //
    // The initialization is O(N^2) and trivially parallel. We:
    //  - traverse in row-major order with j (x) innermost
    //  - tile for cache locality
    //  - vectorize along j (unit-stride)
    //  - parallelize across tiles in y
    //
    Target target = get_jit_target_from_environment();
    int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    Var xo("xo_init"), yo("yo_init"), xi("xi_init"), yi("yi_init");

    init_A
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, TILE_X, TILE_Y)
        .vectorize(xi, vec_width)
        .parallel(yo);

    init_B
        .compute_root()
        .tile(j, i, xo, yo, xi, yi, TILE_X, TILE_Y)
        .vectorize(xi, vec_width)
        .parallel(yo);

    // Realize into the provided buffers.
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n       = N;
    int tsteps  = TSTEPS;

    // Buffers corresponding to A[N][N] and B[N][N].
    // C layout is A[i][j]; we map that to A_buf(j, i).
    Halide::Buffer<num_t, 2> A(n, n);  // x = j, y = i
    Halide::Buffer<num_t, 2> B(n, n);  // x = j, y = i

    // Initialize A and B.
    init_array(n, A, B);

    // -------------------------------
    // Define the Jacobi 2D stencil in Halide
    // -------------------------------

    // ImageParam representing the "current" grid (either A or B).
    ImageParam cur_param(type_of<num_t>(), 2, "cur_param");

    // Vars: x corresponds to column index j, y to row index i.
    Var x("x"), y("y");

    // Factor 0.2 in the correct type.
    Expr w = cast<num_t>(0.2);

    // Jacobi update:
    //
    // B[i][j] = 0.2 * (A[i][j] +
    //                  A[i][j-1] + A[i][j+1] +
    //                  A[i+1][j] + A[i-1][j]);
