    // In Halide coordinates (x=j, y=i):
    // next(x,y) = 0.2 * (cur(x,y) +
    //                    cur(x-1,y) + cur(x+1,y) +
    //                    cur(x,y+1) + cur(x,y-1));
    Func jacobi("jacobi");
    jacobi(x, y) = w * (cur_param(x,     y    ) +
                        cur_param(x - 1, y    ) +
                        cur_param(x + 1, y    ) +
                        cur_param(x,     y + 1) +
                        cur_param(x,     y - 1));

    // -------------------------------
    // Optimized schedule for Jacobi step
    // -------------------------------
    //
    // Each jacobi(x,y) only reads from cur_param and writes a single
    // output point. There are no intra-pass dependencies, so we are
    // free to reorder, tile, vectorize, and parallelize over x,y.
    //
    // We:
    //  - tile the 2D domain into TILE_X-by-TILE_Y tiles
    //  - parallelize over tile rows (yo)
    //  - vectorize along x within a tile (unit-stride memory)
    //  - lightly unroll y inside a tile to expose ILP
    //
    Target target = get_jit_target_from_environment();
    int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    jacobi
        .compute_root()                                  // make scheduling explicit
        .tile(x, y, xo, yo, xi, yi, TILE_X, TILE_Y)      // 2D tiling
        .vectorize(xi, vec_width)                        // SIMD across contiguous x
        .unroll(yi, 2)                                   // small unroll in y
        .parallel(yo);                                   // parallel across tile rows

