    // Only apply the stencil to the interior points:
    // i,j = 1 .. n-2. The boundaries remain unchanged across time
    // steps, matching the original C code.
    // -------------------------------
    //
    // Create interior views of A and B that alias the underlying storage.
    // Dimension 0 is x (j), dimension 1 is y (i).
    //
    // A_interior, B_interior represent [1..n-2]×[1..n-2] in C's (i,j) space
    // and are used as the realization domains. The halo accesses
    // (x±1,y±1) stay within [0..n-1] in the full A/B buffers, so
    // no out-of-bounds reads occur and no explicit boundary conditions
    // are needed.
    Halide::Buffer<num_t, 2> A_interior =
        A.cropped(0, 1, n - 2).cropped(1, 1, n - 2);
    Halide::Buffer<num_t, 2> B_interior =
        B.cropped(0, 1, n - 2).cropped(1, 1, n - 2);

    // Bind some initial buffer (say A) before compiling.
    cur_param.set(A);

    // Compile the Jacobi step once; we'll reuse it for all time steps.
    jacobi.compile_jit(target);

    // -------------------------------
    // Time-stepping loop, driven from the host
    // -------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Original C kernel:
    //
    // for (t = 0; t < tsteps; t++) {
    //   // B from A
    //   for (i = 1; i < n-1; i++)
    //     for (j = 1; j < n-1; j++)
    //       B[i][j] = stencil(A,...);
    //
    //   // A from B
    //   for (i = 1; i < n-1; i++)
    //     for (j = 1; j < n-1; j++)
    //       A[i][j] = stencil(B,...);
    // }
    //
    // We implement the same ping-pong using a single Halide Func "jacobi"
    // and two interior views that alias A and B. Time-stepping remains
    // strictly sequential on the host to preserve Jacobi semantics.
    for (int t = 0; t < tsteps; t++) {
        // First phase: B <- stencil(A)
        cur_param.set(A);
        jacobi.realize(B_interior);

        // Second phase: A <- stencil(B)
        cur_param.set(B);
        jacobi.realize(A_interior);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

