#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Halide-based initialization of A and B.
 *
 * Original C code:
 *
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++) {
 *       A[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
 *       B[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
 *     }
 *
 * We map A[i][j] -> A(j, i) and B[i][j] -> B(j, i) in Halide.
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // n as a Halide Expr, with the correct element type.
    Expr n_expr = cast<num_t>(Expr(n));

    // A(i,j) in C -> A(j,i) in Halide
    init_A(j, i) = cast<num_t>(i * (j + 2) + 2) / n_expr;
    // B(i,j) in C -> B(j,i) in Halide
    init_B(j, i) = cast<num_t>(i * (j + 3) + 3) / n_expr;

    // A and B are each realized once, so a simple row-major schedule is
    // enough here; we rely on Halide's default (x inner, y outer).
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n       = N;
    int tsteps  = TSTEPS;

    // Buffers corresponding to A[N][N] and B[N][N].
    // C layout is A[i][j]; we map that to A_buf(j, i).
    //
    // Dimension 0 (x) is the column index j and is unit-stride in memory
    // (row-major). Dimension 1 (y) is the row index i.
    Halide::Buffer<num_t, 2> A(n, n);  // x = j, y = i
    Halide::Buffer<num_t, 2> B(n, n);  // x = j, y = i

    // Initialize A and B.
    init_array(n, A, B);

    // -------------------------------
    // Define the Jacobi 2D stencil in Halide
    // -------------------------------

    // ImageParam representing the "current" grid (either A or B).
    ImageParam cur_param(type_of<num_t>(), 2, "cur_param");

    // Vars: x corresponds to column index j, y to row index i.
    Var x("x"), y("y");

    // Factor 0.2 in the correct type.
    Expr w = cast<num_t>(Expr(0.2));

    // Jacobi update:
    //
    // B[i][j] = 0.2 * (A[i][j] +
    //                  A[i][j-1] + A[i][j+1] +
    //                  A[i+1][j] + A[i-1][j]);
    //
    // In Halide coordinates (x=j, y=i):
    // next(x,y) = 0.2 * (cur(x,y) +
    //                    cur(x-1,y) + cur(x+1,y) +
    //                    cur(x,y+1) + cur(x,y-1));
    Func jacobi("jacobi");

    // Use explicit local Exprs to make the stencil structure obvious;
    // Halide will common-subexpression-eliminate where profitable.
    Expr center = cur_param(x,     y    );
    Expr left   = cur_param(x - 1, y    );
    Expr right  = cur_param(x + 1, y    );
    Expr down   = cur_param(x,     y + 1);
    Expr up     = cur_param(x,     y - 1);

    jacobi(x, y) = w * (center + left + right + up + down);

    // -------------------------------
    // Optimized CPU schedule for the Jacobi step
    // -------------------------------
    //
    // Key goals:
    //   - Keep x (column / j) as the innermost loop for unit-stride access.
    //   - Tile the 2D domain to improve cache locality.
    //   - Vectorize along x for SIMD.
    //   - Parallelize across tiles in y (row / i).
    //
    // Note: We only ever realize 'jacobi' over the interior region
    // [1..n-2] × [1..n-2] (see A_interior/B_interior below), so the
    // schedule applies to that domain; boundaries are never written,
    // matching the original C code.

    // Choose a reasonable target and vector width based on the host.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile sizes tuned for a modern multi-core x64 CPU. 64×32 gives a
    // good balance between cache locality and parallel granularity, and
    // maintains a tall-enough y dimension to parallelize over.
    const int tile_x = 64;  // columns (j / x)
    const int tile_y = 32;  // rows    (i / y)

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    jacobi
        // Work on 2D tiles of size tile_x × tile_y in (x,y).
        // After tiling, the loop nest is:
        //   for yo:
        //     for xo:
        //       for yi in [0, tile_y):
        //         for xi in [0, tile_x):
        //           compute jacobi(x,y)
        .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
        // Within each tile, keep x (xi) innermost and vectorize along it.
        // This gives contiguous SIMD loads/stores in the row-major layout.
        .vectorize(xi, vec_width)
        // Parallelize across tile-rows (yo). Each (yo, xo) tile writes a
        // disjoint sub-rectangle of the output, so tiles are independent
        // within a single Jacobi phase.
        .parallel(yo)
        // For slightly better ILP inside a tile, unroll a small factor in y.
        .unroll(yi, 2)
        // Make the tiling explicit at the top-level. (For a single-stage
        // Func like this, compute_root() is the default, but stating it
        // keeps the schedule self-contained.)
        .compute_root();

    // We will only apply the stencil to the interior points:
    // i,j = 1 .. n-2. The boundaries remain unchanged across time steps,
    // matching the original C code.
    //
    // Create interior views of A and B that alias the underlying storage.
    // Dimension 0 is x (j), dimension 1 is y (i).
    Halide::Buffer<num_t, 2> A_interior =
        A.cropped(0, 1, n - 2).cropped(1, 1, n - 2);
    Halide::Buffer<num_t, 2> B_interior =
        B.cropped(0, 1, n - 2).cropped(1, 1, n - 2);

    // Bind some initial buffer (say A) before compiling so that
    // Halide knows the dimensionality and element type of cur_param.
    cur_param.set(A);

    // Compile the Jacobi step once; we'll reuse it for all time steps.
    jacobi.compile_jit(target);

    // -------------------------------
    // Time-stepping loop, driven from the host
    // -------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Original C kernel:
    //
    // for (t = 0; t < tsteps; t++) {
    //   // B from A
    //   for (i = 1; i < n-1; i++)
    //     for (j = 1; j < n-1; j++)
    //       B[i][j] = stencil(A,...);
    //
    //   // A from B
    //   for (i = 1; i < n-1; i++)
    //     for (j = 1; j < n-1; j++)
    //       A[i][j] = stencil(B,...);
    // }
    //
    // We implement the same ping-pong using a single Halide Func "jacobi":
    // each phase uses 'cur_param' bound to the current grid and realizes
    // into the interior slice of the other grid.
    for (int t = 0; t < tsteps; t++) {
        // First phase: B <- stencil(A)
        cur_param.set(A);
        jacobi.realize(B_interior);

        // Second phase: A <- stencil(B)
        cur_param.set(B);
        jacobi.realize(A_interior);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------
    // Optional: print the final A to stderr
    // (similar intent to polybench_prevent_dce(print_array))
    // -------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Recall A(i,j) in C is A(j,i) in Halide.
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds to stdout, with microsecond precision.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
